local GemMiner = {}
local PRODUCTS = {
    quartz_gem = { name = "Kvarčni dragulj", gemVeinCost = 1, time = 2, cost = 25, quality = 30, prestige = 1, description = "Kvarčni dragulj iz rudnika." },
    amethyst = { name = "Ametist", gemVeinCost = 1, time = 3, cost = 60, quality = 50, prestige = 3, description = "Ametist z vijolično barvo." },
    sapphire = { name = "Safir", gemVeinCost = 1, time = 5, cost = 150, quality = 65, prestige = 6, happiness = 1, description = "Safir z modro barvo." },
    ruby = { name = "Rubin", gemVeinCost = 1, time = 7, cost = 350, quality = 80, prestige = 12, happiness = 2, description = "Rubin z rdečo barvo." },
    emerald = { name = "Smaragd", gemVeinCost = 1, silverCost = 1, time = 10, cost = 750, quality = 92, prestige = 20, happiness = 4, description = "Smaragd z zeleno barvo." },
    royal_grand_diamond = { name = "Kraljevski veliki diamant", gemVeinCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, time = 16, cost = 2500, quality = 100, prestige = 55, happiness = 11, description = "Veliki kraljevski diamant z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Draguljska postaja", cost = { gold = 350, wood = 100, stone = 250 }, upkeep = 9, qualityBonus = 5 },
    gem_mine = { name = "Draguljski rudnik", cost = { gold = 1200, wood = 250, stone = 500, iron = 10 }, upkeep = 30, qualityBonus = 18 },
    cutting_house = { name = "Rezalnica", cost = { gold = 2800, wood = 350, stone = 800, silver = 50, steel = 8 }, upkeep = 70, qualityBonus = 30 },
    royal_gem_atelier = { name = "Kraljevski atelje draguljev", cost = { gold = 11000, wood = 600, stone = 1200, gold = 80, jewel = 25 }, upkeep = 220, qualityBonus = 55, prestigeBonus = 45 },
}
GemMiner.gemVeinStock = 18; GemMiner.silverStock = 8; GemMiner.goldStock = 6; GemMiner.jewelStock = 6
GemMiner.productStock = {}; GemMiner.buildings = {}; GemMiner.maker = nil; GemMiner.activeMaking = {}; GemMiner.totalProducts = 0; GemMiner.dayTimer = 0
function GemMiner.init() GemMiner.gemVeinStock=18; GemMiner.silverStock=8; GemMiner.goldStock=6; GemMiner.jewelStock=6; GemMiner.productStock={}; GemMiner.buildings={}; GemMiner.maker=nil; GemMiner.activeMaking={}; GemMiner.totalProducts=0; GemMiner.dayTimer=0; print("[GemMiner] Royal Gem Miner System initialized (6 products, 4 buildings)") end
function GemMiner.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GemMiner.maker={name=n or ("Draguljar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Draguljar najet: %s (spretnost: %d)",GemMiner.maker.name,s),"success") end; return true end
function GemMiner.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GemMiner.build(id) local ok,e=GemMiner.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GemMiner.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GemMiner.getQualityBonus() local b=0; for _,bd in ipairs(GemMiner.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GemMiner.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.gemVeinCost and GemMiner.gemVeinStock<(d.gemVeinCost or 0) then return false,"Premalo draguljskih žil" end; if d.silverCost and GemMiner.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GemMiner.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GemMiner.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #GemMiner.buildings==0 then return false,"Potrebna delavnica" end; if not GemMiner.maker then return false,"Potreben draguljar" end; return true end
function GemMiner.make(pt,qty) qty=qty or 1; local ok,e=GemMiner.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.gemVeinCost then GemMiner.gemVeinStock=GemMiner.gemVeinStock-d.gemVeinCost*qty end; if d.silverCost then GemMiner.silverStock=GemMiner.silverStock-d.silverCost*qty end; if d.goldCost then GemMiner.goldStock=GemMiner.goldStock-d.goldCost*qty end; if d.jewelCost then GemMiner.jewelStock=GemMiner.jewelStock-d.jewelCost*qty end; local t=d.time; if GemMiner.maker then t=math.max(1,t-math.floor(GemMiner.maker.skill/12)) end; table.insert(GemMiner.activeMaking,{id="gem_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,quality=d.quality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GemMiner.completeMaking(m) local q=1.0+(GemMiner.getQualityBonus()/100); if GemMiner.maker then q=q+(GemMiner.maker.skill/150) end; q=math.min(2.5,q); GemMiner.productStock[m.productType]=(GemMiner.productStock[m.productType] or 0)+m.quantity; GemMiner.totalProducts=GemMiner.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GemMiner.maker then GemMiner.maker.itemsMade=GemMiner.maker.itemsMade+m.quantity; if math.random()<0.25 then GemMiner.maker.skill=math.min(100,GemMiner.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dragulj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gem.completed",{productName=m.productName,quality=m.quality,prestige=m.prestige}) end end
function GemMiner.update(dt) if not _G.state then return end; GemMiner.dayTimer=GemMiner.dayTimer+dt; if GemMiner.dayTimer>=30 then GemMiner.dayTimer=0; for i=#GemMiner.activeMaking,1,-1 do local m=GemMiner.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GemMiner.completeMaking(m); table.remove(GemMiner.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GemMiner.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GemMiner.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GemMiner.getStats() return {gemVeinStock=GemMiner.gemVeinStock,silverStock=GemMiner.silverStock,goldStock=GemMiner.goldStock,jewelStock=GemMiner.jewelStock,productStock=GemMiner.productStock,numBuildings=#GemMiner.buildings,hasMaker=GemMiner.maker~=nil,makerName=GemMiner.maker and GemMiner.maker.name or "—",makerSkill=GemMiner.maker and GemMiner.maker.skill or 0,activeMaking=#GemMiner.activeMaking,totalProducts=GemMiner.totalProducts} end
return GemMiner
